window.FILM_WORK_PROMPTS={"work_id":"src-ae4e659644d3156a","records":[{"id":"VP-src-ae4e659644d3156a-01","work_id":"src-ae4e659644d3156a","frame_id":"IM-src-ae4e659644d3156a-rm2534192897-01","source_url":"https://m.media-amazon.com/images/M/MV5BYTBlMjdkNzYtNDU0ZC00ZTEyLTk5MmItMWViOWYzOWFkNTMxXkEyXkFqcGc@._V1_.jpg","source_page":"https://www.imdb.com/title/tt0113725/mediaviewer/rm2534192897/","scene":"对称深邃的传统日式老宅门廊中央身穿黑色丧服的女子端坐在两扇亮白门窗光框之间","analysis":"是枝裕和与摄影师中堀正夫经典的高反差几何框架构图，大面积幽暗的室内阴影与两侧刺眼的矩形白光将居中的黑衣女子衬托得如同凝固的祭奠雕像。","prompt":"高对比度明暗对称中全景镜头，在一间幽暗深邃的日本传统木结构老宅走廊内，身穿纯黑色传统和服丧服的女主角端正地跪坐在画面正中央的阴影里；她左右两侧对称分布着两扇透进刺眼白色日光的长方形门窗框，强烈的明暗反差营造出庄重而寂寥的禅意空间，画面呈现出细腻自然的胶片颗粒质感与层次丰富的光影过渡。","model":"manual-visual-inspection","verification":"观图待人工核","review":"Antigravity 逐帧观图核验 (2026-10-20)","review_version":"antigravity-visual-audit-v1","created":"2026-10-21T09:00:03.195237+00:00","origin":"visual"},{"id":"VP-src-ae4e659644d3156a-02","work_id":"src-ae4e659644d3156a","frame_id":"IM-src-ae4e659644d3156a-rm2282534657-02","source_url":"https://m.media-amazon.com/images/M/MV5BMTBkMDkwNDktMDdmNi00MGQxLWIwYmUtN2FjNzQ5MjY5YjM4XkEyXkFqcGc@._V1_.jpg","source_page":"https://www.imdb.com/title/tt0113725/mediaviewer/rm2282534657/","scene":"挂满晶莹雨珠的夜班列车车窗旁江角真纪子低垂着眼帘陷入沉默的哀思之中","analysis":"采用幽暗唯美的低调夜景摄影与前景焦外光斑构图，车窗玻璃上的细密雨滴与远处橘黄色的散景光斑映照出女主人公内心的孤独与凄楚。","prompt":"低照度夜景近景特写镜头，在一辆夜间行驶的列车或巴士车厢内，留着黑色短发的江角真纪子位于画面右侧，以侧面姿态低垂着头静静坐着；画面左侧紧贴着一扇布满细密水珠与雨痕的玻璃窗，窗外深邃的夜色中闪烁着绿色与暖橙色的朦胧散景光斑，画面呈现出细腻自然的胶片颗粒质感与层次丰富的光影过渡。","model":"manual-visual-inspection","verification":"观图待人工核","review":"Antigravity 逐帧观图核验 (2026-10-20)","review_version":"antigravity-visual-audit-v1","created":"2026-10-21T09:00:03.195237+00:00","origin":"visual"},{"id":"VP-src-ae4e659644d3156a-03","work_id":"src-ae4e659644d3156a","frame_id":"IM-src-ae4e659644d3156a-rm2383197953-03","source_url":"https://m.media-amazon.com/images/M/MV5BZDI2NjA5YTEtNGI0NS00YjQ0LWE2MzEtNzIwZDkyNjczM2YzXkEyXkFqcGc@._V1_.jpg","source_page":"https://www.imdb.com/title/tt0113725/mediaviewer/rm2383197953/","scene":"阴云低垂的静谧湖岸堤坝上两个微小的人影正沿着倒映着青山的水边小径缓步前行","analysis":"极简主义东方美学大远景构图，大面积灰白如镜的水面与深黛色的山体倒影将画面一分为二，天地间渺小的人影流露出物哀式的生命哲思。","prompt":"极简主义冷灰调大远景镜头，在铅灰色阴云笼罩的开阔水岸边，一道深黑色的斜向堤岸与远山轮廓将画面分割开来，平静如镜的灰白色水面上清晰倒映着山影与两个并肩行走的微小黑色人影，整幅画面静谧空灵，散发着深沉的东方诗意与宿命感，画面呈现出细腻自然的胶片颗粒质感与层次丰富的光影过渡。","model":"manual-visual-inspection","verification":"观图待人工核","review":"Antigravity 逐帧观图核验 (2026-10-20)","review_version":"antigravity-visual-audit-v1","created":"2026-10-21T09:00:03.195237+00:00","origin":"visual"}]};